CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
             JOIN public.organizations o ON o.id = m.organization_id
            WHERE m.organization_id = p_org_id
              AND m.user_id = (SELECT auth.uid())
              AND (m.role IN ('broker', 'admin')
                   OR o.personal_owner_user_id = m.user_id)
         )
     AND COALESCE((public.check_feature_access(p_org_id, 'transaction_checklists') ->> 'allowed')::boolean, false);
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public.can_edit_checklist_templates(uuid)'::regprocedure) NOT LIKE '%''it_admin''%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('it_admin removed') AS mutation;
